import {useState} from 'react';import{createRoot}from'react-dom/client';import Redesign from '../../src/redesign/Redesign';import type{State}from'../../src/redesign/model';
const make=(id:string,name:string,group='Personal')=>({id,name,group,template:'Grocery',items:['Milk','Bread','Eggs'].map((title,index)=>({id:id+index,title,done:false,fields:{}}))});
const initial:State={version:1,defaultTheme:'blue',openingGroup:'Personal',listOrder:['second','first','work2','work1'],lists:[make('first','To-Do'),make('second','Grocery'),make('work1','Work one','Work'),make('work2','Work two','Work')]};
function Preview(){const [state,setState]=useState<State>(()=>JSON.parse(localStorage.getItem('test-state')||'null')||initial);return <Redesign initialState={state} onSave={next=>{(window as any).__saved=next;localStorage.setItem('test-state',JSON.stringify(next));setState(next)}} roles={new URLSearchParams(location.search).has('viewer')?{second:'viewer'}:{}} accountControls={<section className="r-account-settings"><h3>Account</h3><p>test@example.com</p><button>Sign out</button></section>}/>};createRoot(document.getElementById('root')!).render(<Preview/>);
